-- Write the full Executive Virtual Assistant course.
-- Content remains draft and unpublished until practitioner review.

update public.training_courses
set estimated_minutes = 360,
    content_version = content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    status = 'draft',
    published_at = null,
    updated_at = now()
where slug = 'executive-virtual-assistant';

update public.training_lessons l
set content = '[{"type":"heading","text":"What executive support is really for"},{"type":"paragraph","text":"An Executive Virtual Assistant is not simply a faster task taker. The role exists to reduce avoidable friction around an executive''s time, attention, decisions, communication, and follow-through. That means understanding the purpose behind requests, keeping context together, surfacing exceptions early, and making routine work easier to trust."},{"type":"heading","text":"The five jobs behind the job"},{"type":"list","items":["Protect focus: reduce unnecessary interruptions and make calendar time reflect actual priorities.","Protect context: keep the information, links, decisions, and history needed for the next action together.","Protect commitments: track what the executive promised, delegated, approved, or needs to decide.","Protect communication: make sure messages are timely, accurate, and appropriate for the audience.","Protect continuity: leave records and handoffs that another person can follow without reconstructing the day."]},{"type":"heading","text":"Task execution versus executive support"},{"type":"paragraph","text":"A task executor waits for a complete instruction. An executive-support professional often receives an incomplete signal: ''Move this,'' ''Can you sort next week?'', ''I need the numbers before the call,'' or ''Follow up with them.'' Your responsibility is to clarify the intended outcome, gather the relevant context, complete what is clearly within your authority, and escalate the decision points that are not."},{"type":"callout","title":"Do not confuse initiative with authority","text":"Initiative means moving approved work forward without being chased. It does not mean making commitments, changing priorities, spending money, disclosing sensitive information, or speaking for the executive beyond the authority you were given."},{"type":"heading","text":"Build an executive operating map"},{"type":"steps","items":["List the executive''s recurring responsibilities: leadership meetings, client work, sales, hiring, operations, finance, board or investor work, travel, and personal commitments if included in scope.","Identify the people and groups who need regular access to the executive.","Identify which calendars, inboxes, task systems, drives, CRMs, and messaging tools are sources of truth.","Document the executive''s approval limits, preferred communication channels, working hours, time zones, travel buffers, and meeting preferences.","Define what counts as urgent and who to contact when the executive is unavailable.","Create a short list of decisions you can make independently, decisions that need approval, and decisions that must never be delegated to you."]},{"type":"heading","text":"A useful mental model: filter, prepare, route"},{"type":"list","items":["Filter: remove noise, duplicates, low-value interruptions, and information that does not require the executive.","Prepare: collect the context, options, documents, dates, and risks needed for a decision.","Route: send the issue to the correct owner with a clear next action and deadline."]},{"type":"scenario","title":"The vague request","text":"Your executive messages: ''Can you handle the investor call next week?'' Do not assume this means cancel, reschedule, prepare slides, or attend in their place. Check the current calendar event, prior notes, attendees, and open actions. Then clarify the desired outcome with a concise question and move only the parts you are authorized to handle."},{"type":"heading","text":"What strong executive support looks like"},{"type":"list","items":["The executive sees fewer avoidable surprises.","Meetings start with the right context and end with clear actions.","Calendar changes do not create hidden conflicts.","Important messages are surfaced without forwarding every message as urgent.","Delegated tasks are visible and followed through.","Research is concise, sourced, and decision-ready.","Handoffs show what changed, what is blocked, and what needs a decision."]},{"type":"heading","text":"Common beginner mistakes"},{"type":"list","items":["Treating every request as urgent because it came from the executive.","Completing the visible task without checking what depends on it.","Sending long updates that hide the decision needed.","Changing schedules without checking travel, preparation, or stakeholder impact.","Using memory instead of a reliable task and decision system.","Trying to look proactive by making decisions outside delegated authority."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Choose a fictional founder or senior manager. Write a one-page operating map covering their recurring responsibilities, important stakeholders, systems, urgency rules, approval boundaries, and the five most common types of support they would need from an Executive VA."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'the-executive-assistant-operating-model';

update public.training_lessons l
set content = '[{"type":"heading","text":"Executive access creates executive-level responsibility"},{"type":"paragraph","text":"Executive assistants often see information before most of the organization does: hiring plans, salaries, performance concerns, customer disputes, pricing, contracts, board material, investor discussions, travel details, personal schedules, passwords, and financial information. The ability to access information is not permission to reuse, forward, summarize, or discuss it outside the approved purpose."},{"type":"heading","text":"Classify before you share"},{"type":"list","items":["Public: already intended for external use.","Internal: routine business information meant for appropriate team members.","Confidential: sensitive business or personal information that should be limited to named or authorized people.","Highly restricted: credentials, banking data, legal strategy, protected personal information, unreleased transactions, security details, or other information the client specifically limits."]},{"type":"heading","text":"The minimum-necessary rule"},{"type":"paragraph","text":"When someone needs information to complete a task, share only what they need for that task. A vendor may need the executive''s arrival time, but not the full itinerary. A meeting attendee may need the approved agenda, but not private notes about another attendee. A colleague may need a decision, but not the confidential background that led to it."},{"type":"callout","title":"Access is not ownership","text":"Do not move client information into your personal drive, personal email, public AI tool, or personal notes simply because that feels easier. Use approved systems and follow the client''s retention and access rules."},{"type":"heading","text":"Define authority in writing"},{"type":"list","items":["Calendar authority: what may be accepted, declined, moved, or held without asking.","Communication authority: what may be drafted, sent, acknowledged, or answered from the executive''s account.","Spending authority: whether you may book or purchase, and any limits.","Information authority: what may be shared with which groups.","Delegation authority: whether you may assign work to staff or vendors.","Emergency authority: what you may do when the executive cannot be reached."]},{"type":"heading","text":"A judgment test before acting"},{"type":"steps","items":["Is this action clearly within my documented authority?","Could it create a financial, legal, privacy, reputation, employment, or relationship consequence?","Would the executive reasonably expect to know before this action happens?","Is the information I am using current and verified?","Can I reverse the action easily if new information appears?","If I am uncertain, can I prepare the options and ask for a decision instead?"]},{"type":"scenario","title":"The confidential candidate","text":"You see a calendar hold for a confidential interview with someone who currently works at a partner company. A colleague asks why the executive is unavailable. Do not reveal the interview. Give only the scheduling information the colleague needs, such as ''They are unavailable during that time. I can offer 3:30 PM or tomorrow morning.''"},{"type":"heading","text":"Writing notes that may outlive the moment"},{"type":"list","items":["Record facts and decisions, not gossip.","Avoid insulting or speculative descriptions of people.","Do not paste confidential content into broad team channels.","Separate personal reminders from formal records.","Use restricted folders or systems when the information requires it.","Assume internal notes may later be reviewed by the client, HR, legal counsel, auditors, or another assistant."]},{"type":"heading","text":"When to escalate immediately"},{"type":"list","items":["Suspected account compromise or credential exposure.","Request to send money or change banking details outside the normal approval process.","Unexpected request for confidential employee, customer, investor, or legal information.","A message that could materially commit the executive or company.","A privacy mistake, accidental recipient, or sensitive file sent to the wrong person.","A situation where the executive''s documented instructions conflict with a new high-risk request."]},{"type":"scenario","title":"The urgent payment message","text":"A message appearing to come from the executive asks you to urgently pay a new supplier using bank details in the email. Even if the tone sounds familiar, follow the client''s payment-verification process. Do not bypass normal approval because the message says ''urgent''."},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a fictional authority matrix with three columns: ''I may do this independently'', ''I may prepare this but need approval'', and ''I must escalate''. Include at least five calendar, communication, spending, information-sharing, and delegation examples."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'confidentiality-judgment-and-authority';

update public.training_lessons l
set content = '[{"type":"heading","text":"An executive inbox is a decision system"},{"type":"paragraph","text":"The goal is not to make the inbox look empty. The goal is to make important messages visible, routine messages handled correctly, commitments tracked, and decisions easy to make. A clean inbox that hides an unanswered customer escalation is worse than a busy inbox with a reliable system."},{"type":"heading","text":"Triage by required outcome"},{"type":"list","items":["Decision: the executive must choose, approve, decline, or give direction.","Action: someone must do something, but the executive may not need to do it personally.","Reply: a response is needed and may be draftable from known information.","Meeting: the message should become or change a calendar event.","Reference: useful information with no current action.","Waiting: another person owes information or a response.","Noise: newsletters, automated notifications, duplicates, or low-value messages handled according to client rules."]},{"type":"heading","text":"Build a first-pass routine"},{"type":"steps","items":["Scan for security, money, legal, customer, employee, or same-day operational issues.","Check messages from high-priority people defined by the executive.","Identify decisions and deadlines.","Process routine replies and routing within your authority.","Create tasks for work that cannot be finished immediately.","Draft responses where context is clear.","Mark or summarize the small set of items the executive truly needs to see.","Run another short scan later instead of interrupting the executive for every new email."]},{"type":"callout","title":"Urgent is not the same as important","text":"A sender can write ''URGENT'' in a subject line without the issue being genuinely urgent. Use the executive''s agreed urgency rules: deadline, impact, source, consequence, and whether delay prevents someone else from acting."},{"type":"heading","text":"Drafting in the executive''s voice"},{"type":"list","items":["Use the executive''s normal level of formality and brevity.","Preserve facts, numbers, dates, and commitments exactly.","Do not invent enthusiasm, approval, pricing, or promises.","Use placeholders or comments where a decision is still needed.","Make the requested action obvious.","Read the entire thread before drafting so you do not repeat a question already answered."]},{"type":"heading","text":"A useful executive summary for an email"},{"type":"steps","items":["What this is about.","What changed since the last update.","What decision or action is needed.","When it is needed.","Your recommended administrative next step, if clearly within scope.","Link or attach the source material."]},{"type":"scenario","title":"The 18-message thread","text":"A client thread contains 18 replies. The latest message asks whether the project can move to Friday, but the thread also shows that finance approval is still outstanding. Do not draft ''Friday works'' unless the executive has authority and has decided. Summarize the dependency, surface the decision, and prepare a response that can be sent once approved."},{"type":"heading","text":"Inbox actions that create hidden problems"},{"type":"list","items":["Archiving a message before its action is captured elsewhere.","Forwarding sensitive threads to broad distribution lists.","Using ''reply all'' without checking who should receive the information.","Drafting from the newest email without reading the prior context.","Marking messages unread as the only reminder system.","Deleting automated emails that contain confirmation numbers or important receipts."]},{"type":"heading","text":"End-of-pass checklist"},{"type":"list","items":["All genuine urgent items surfaced.","Every decision has enough context.","Every delegated action has an owner.","Every waiting item has a follow-up date if needed.","Drafts do not contain invented commitments.","Sensitive information stayed in approved systems."]},{"type":"scenario","title":"Practice triage","text":"Imagine 12 incoming messages: an employee resignation, a newsletter, a same-day customer complaint, a meeting invitation, a supplier invoice, a password-reset alert, a sales pitch, a board-paper update, a travel confirmation, a colleague asking for a file, a client reschedule request, and a routine report. Sort them by outcome and explain the first five actions you would take."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'executive-inbox-triage-and-drafting';

update public.training_lessons l
set content = '[{"type":"heading","text":"A calendar is a model of priorities"},{"type":"paragraph","text":"Executive calendar management is not about fitting the maximum number of meetings into every open space. A useful calendar protects preparation time, travel, deep work, decision windows, personal constraints, recovery after demanding sessions, and the commitments that only the executive can fulfill."},{"type":"heading","text":"Know the scheduling rules before moving anything"},{"type":"list","items":["Working hours and protected personal time.","Preferred meeting lengths.","Minimum buffers between calls.","Travel or commute requirements.","Time-zone preferences.","Days reserved for internal versus external meetings.","Recurring leadership, board, customer, sales, or team commitments.","Who may book directly and who requires approval."]},{"type":"heading","text":"Read the whole calendar, not just the empty slot"},{"type":"steps","items":["Check the meeting before and after the proposed time.","Check whether preparation or document review is needed.","Check location or video platform.","Check attendee time zones.","Check whether the executive must travel.","Check for soft holds, personal blocks, or recurring commitments.","Check whether moving this event creates work for other people.","Confirm the change in the source calendar and communicate it to affected attendees."]},{"type":"callout","title":"Available does not mean usable","text":"A 30-minute empty slot between two meetings may be unusable if the executive needs 20 minutes to travel, review a document, eat, or make a private call. Protect the real operating constraint, not only the visible free space."},{"type":"heading","text":"Use holds deliberately"},{"type":"list","items":["Temporary hold: reserve a possible time while waiting for confirmation.","Preparation block: protect time needed before a meeting.","Travel block: make movement time visible.","Focus block: preserve uninterrupted work.","Decision block: group approvals or review work.","Recovery buffer: prevent a high-intensity meeting from flowing directly into another critical conversation."]},{"type":"heading","text":"Time-zone discipline"},{"type":"list","items":["Confirm the attendee''s local zone when the relationship spans locations.","Avoid relying on abbreviations that can be ambiguous.","Include the local date as well as time when a meeting crosses midnight in another zone.","Check daylight-saving changes when relevant.","Use the calendar system''s time-zone support rather than manual mental conversion whenever possible."]},{"type":"scenario","title":"The apparently open hour","text":"A London-based investor requests 9:00 AM their time. Your executive is travelling in Singapore that week. The calendar is empty at the converted time, but the itinerary shows an airport transfer ending 20 minutes earlier. Flag the travel risk and offer realistic alternatives instead of accepting merely because the calendar cell is open."},{"type":"heading","text":"Handling conflicting priorities"},{"type":"steps","items":["Identify which commitments are fixed and which can move.","Identify the consequence of moving each one.","Check whether another person can represent the executive.","Prepare two or three workable options.","Explain the trade-off briefly.","Get the required approval.","Communicate the chosen change to everyone affected.","Update related prep tasks, travel, rooms, links, and reminders."]},{"type":"heading","text":"Calendar hygiene"},{"type":"list","items":["Clear title that explains the purpose.","Correct attendee list.","Correct location or meeting link.","Useful agenda or context link.","Time zone checked.","Required preparation linked.","Cancelled meetings actually removed or marked clearly.","Changes communicated rather than silently edited when people are affected."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Build a fictional Tuesday with eight meetings across two time zones, one travel block, one focus block, and a 90-minute preparation requirement. Then introduce a new urgent customer call and show how you would resolve the conflict without simply deleting the focus time."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'complex-calendar-management';

update public.training_lessons l
set content = '[{"type":"heading","text":"A meeting should not start with reconstruction"},{"type":"paragraph","text":"Executive meeting preparation should reduce the amount of time spent asking, ''Why are we meeting?'', ''Where is the file?'', ''What did we decide last time?'', and ''What do you need from me?'' A good briefing note makes the purpose, context, decisions, and risks visible before the call starts."},{"type":"heading","text":"Start with the intended outcome"},{"type":"list","items":["Inform: the executive needs an update.","Decide: one or more choices must be made.","Approve: a proposal, budget, hire, timeline, or document needs authorization.","Resolve: a blocker or disagreement needs action.","Prepare: participants must align before a later event.","Build relationship: the main objective is connection, trust, or stakeholder management."]},{"type":"heading","text":"A practical briefing note"},{"type":"steps","items":["Meeting title, date, time, location, and attendees.","Purpose in one sentence.","Background in a few lines.","What changed since the last interaction.","Open decisions or questions.","Important numbers, deadlines, or commitments.","Documents and links.","Known sensitivities or risks.","Desired outcome and immediate next step."]},{"type":"callout","title":"Brief means decision-ready, not incomplete","text":"A one-page note that leaves out the only important dependency is not better than a two-page note that contains the facts needed to decide. Remove repetition, not necessary context."},{"type":"heading","text":"Agenda design"},{"type":"list","items":["Put decisions before low-value updates when possible.","Give each major item an owner.","Estimate time realistically.","Separate discussion from approval.","Mark pre-reading clearly.","End with actions, owners, and deadlines.","Do not add agenda items simply because someone mentioned them if they do not belong in this meeting."]},{"type":"heading","text":"Research the people without becoming invasive"},{"type":"paragraph","text":"For external meetings, basic professional context may help: role, company, prior interactions, stated priorities, and relevant public information. Do not collect unnecessary personal information or turn public-profile research into speculation about someone''s motives, finances, family, health, or private life."},{"type":"scenario","title":"The meeting with missing context","text":"Your executive has a 20-minute call with a potential partner. The calendar title only says ''Catch up''. Search the CRM, email history, prior meeting notes, and relevant company material. Prepare a short note explaining the relationship, last discussion, outstanding proposal, and one decision the executive may need to make."},{"type":"heading","text":"Pre-meeting QA"},{"type":"list","items":["All attendees are correct.","The correct version of each document is linked.","The executive knows what decision is expected.","Any numbers in the brief match the source.","Sensitive information is shared only with the intended audience.","The calendar link works.","Any required preparation has enough time scheduled before the meeting."]},{"type":"heading","text":"Common preparation failures"},{"type":"list","items":["Sending ten attachments without saying which one matters.","Using an old deck because it had the same filename.","Writing biographies instead of decision context.","Copying internal commentary into a document shared externally.","Preparing a perfect agenda but no owner for the follow-up.","Waiting until five minutes before the meeting to notice a missing file."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Prepare a fictional one-page briefing note for a 30-minute client renewal meeting. Include purpose, attendee context, account history, current issue, renewal date, two open decisions, source links, and the desired outcome."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'meeting-preparation-agendas-and-briefing-notes';

update public.training_lessons l
set content = '[{"type":"heading","text":"Meeting notes are valuable only when they change what happens next"},{"type":"paragraph","text":"A transcript is not the same as a useful record. Executive support focuses on decisions, commitments, open questions, owners, deadlines, and the minimum context needed to understand them later."},{"type":"heading","text":"Separate the record into four types"},{"type":"list","items":["Decision: what was agreed or rejected.","Action: what someone must do next.","Open question: what remains unresolved.","Reference: important context that may matter later but requires no action now."]},{"type":"heading","text":"Write actions so they can be executed"},{"type":"steps","items":["Start with a clear verb.","Name the owner.","Describe the expected output.","Add the deadline.","Link the source material.","Note dependencies or approval requirements.","Put the action in the team''s actual task system rather than leaving it only in the meeting document."]},{"type":"callout","title":"Do not invent agreement","text":"If participants discussed an option but did not decide, record it as unresolved. Turning a discussion into a ''decision'' can create real operational and relationship problems."},{"type":"heading","text":"Minutes versus executive notes"},{"type":"paragraph","text":"Some meetings need formal minutes; others need a short action summary. Follow the client''s process. Formal governance, board, legal, HR, or regulated meetings may have special requirements, and a VA should not improvise a record standard that the organization treats as official."},{"type":"heading","text":"Follow-up sequence"},{"type":"steps","items":["Review notes while the meeting is still fresh.","Confirm ambiguous owners or dates before publishing the record.","Send the approved summary to the correct audience.","Create tasks in the source task system.","Schedule reminders or checkpoints.","Update CRM, project, or account records if required.","Escalate overdue or blocked commitments according to the agreed cadence."]},{"type":"scenario","title":"Three people volunteered"},{"type":"paragraph","text":"During a meeting, three people say they can help with a launch checklist, but nobody is clearly assigned. Do not record all three as owners and hope someone acts. Mark the ownership as unresolved and ask the meeting leader to confirm one accountable owner."},{"type":"heading","text":"Stakeholder follow-up"},{"type":"list","items":["Internal colleague: include the decision, task, due date, and dependency.","Client: confirm agreed next steps and anything you still need from them.","Vendor: confirm approved scope, timing, and required deliverables.","Senior stakeholder: lead with the decision or exception, not a diary of the whole meeting.","Executive: summarize what changed, what is blocked, and where their input is required."]},{"type":"heading","text":"Quality checks"},{"type":"list","items":["Names and companies are correct.","Decisions match what was actually agreed.","Actions have one accountable owner.","Deadlines are specific.","Sensitive notes are not included in the wrong version.","Links point to the correct document versions.","Follow-up tasks exist outside the meeting note."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Use a fictional meeting with six discussion points. Produce a concise summary containing two decisions, four actions, one unresolved question, and one stakeholder follow-up email. Make every action independently understandable."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'minutes-actions-and-stakeholder-follow-up';

update public.training_lessons l
set content = '[{"type":"heading","text":"Travel planning is a dependency problem"},{"type":"paragraph","text":"Executive travel combines time, cost, location, approvals, identity details, meeting schedules, transport, accommodation, cancellation rules, and contingency. A VA''s job is to make the options and dependencies clear, not to optimize one variable while ignoring the rest."},{"type":"heading","text":"Clarify the brief before searching"},{"type":"list","items":["Destination and purpose.","Required arrival and departure windows.","Meetings that cannot move.","Preferred airports, airlines, cabin, hotels, or loyalty programs if supplied.","Budget or approval limits.","Ground transport needs.","Baggage or equipment requirements.","Accessibility, dietary, or other approved travel needs.","Passport, visa, or entry-document responsibility according to the client''s process."]},{"type":"heading","text":"Compare options consistently"},{"type":"steps","items":["Use the same criteria for each option.","Show local departure and arrival times.","Include total travel time, not just flight duration.","Show connections and connection length.","Note fare or booking flexibility when relevant.","Show the true total cost available from the approved booking source.","Explain the trade-off in one sentence.","Do not purchase until the required approval is clear."]},{"type":"callout","title":"Do not guess entry requirements","text":"Visa, passport, vaccination, customs, and border requirements can change and may depend on citizenship and itinerary. Use current official sources or the client''s approved travel provider and make the executive responsible for professional or government advice where required."},{"type":"heading","text":"Build an itinerary someone can actually use"},{"type":"list","items":["All dates shown in local time.","Flight/train details and confirmation references.","Airport or station transfer.","Hotel address and confirmation.","Meeting locations and travel time.","Key contact details.","Required check-in or checkout times.","Relevant documents linked securely.","Time-zone notes where useful.","Contingency contact or approved travel provider."]},{"type":"heading","text":"Privacy and identity data"},{"type":"paragraph","text":"Passport numbers, dates of birth, loyalty details, home addresses, payment cards, and identity documents should be handled only in approved systems and shared only when required for the booking. Avoid placing sensitive identity data into broad itinerary documents."},{"type":"scenario","title":"Cheapest is not best","text":"One flight is $150 cheaper but lands 75 minutes before a critical meeting across the city. Another arrives the night before. Present the timing and cost trade-off rather than recommending the cheapest option without considering the actual business requirement."},{"type":"heading","text":"Booking QA"},{"type":"list","items":["Traveller name matches the approved identity information.","Dates are correct.","Departure and arrival cities/airports are correct.","Time zones checked.","Required approval recorded.","Cancellation/change conditions noted where relevant.","Confirmation stored in the source system.","Calendar and itinerary updated after booking."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Prepare a fictional two-city three-day executive trip. Compare two travel options, explain the trade-offs, create a simple itinerary, and list the approvals you would need before purchasing anything."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'travel-planning-and-itinerary-administration';

update public.training_lessons l
set content = '[{"type":"heading","text":"The quality of support shows when the plan breaks"},{"type":"paragraph","text":"Travel and executive schedules change. Flights cancel, meetings move, executives run late, rooms become unavailable, customers escalate, and priorities shift. Strong support does not pretend disruption can be eliminated. It creates a calm process for understanding impact, producing options, communicating changes, and preserving the next critical commitment."},{"type":"heading","text":"First response to disruption"},{"type":"steps","items":["Confirm what changed from a reliable source.","Identify the immediate consequence.","Find the next time-sensitive dependency.","Check the executive''s delegated authority and preferences.","Prepare the minimum viable options.","Escalate the decision if required.","Communicate only confirmed changes.","Update calendar, itinerary, tasks, and stakeholders after the decision."]},{"type":"callout","title":"Do not solve one problem by creating three new ones","text":"Moving a flight may affect a hotel, driver, customer meeting, dinner, check-in, colleague, or next-day presentation. Check downstream dependencies before confirming the new option."},{"type":"heading","text":"Contingency options should be decision-ready"},{"type":"list","items":["Option and availability.","Cost or fee if known.","Timing impact.","What else must change.","Approval required.","Deadline to decide.","Fallback if the option disappears."]},{"type":"heading","text":"Communication order during disruption"},{"type":"list","items":["People affected by immediate safety or access.","People whose action is needed to resolve the issue.","Stakeholders whose meeting or commitment will change.","Internal teams who need the revised plan.","Other parties who can wait until the new plan is confirmed."]},{"type":"scenario","title":"Cancelled flight before a client meeting","text":"A flight is cancelled and the executive is due at an in-person client meeting the next morning. Check alternate flights, remote-meeting possibility, travel time from alternate airports, hotel impact, and the client''s availability. Present options and get the required decision before promising a new plan to the client."},{"type":"heading","text":"When the executive is unreachable"},{"type":"paragraph","text":"Use the client''s documented emergency authority. If none exists, do not invent one. Take reversible administrative actions where clearly allowed, hold options if the booking system permits, notify the agreed backup person, and preserve a concise record of what happened and what decision is pending."},{"type":"heading","text":"Disruption handoff"},{"type":"steps","items":["What happened and when.","Current confirmed status.","Who has been contacted.","Options currently available.","Decision required.","Deadline to decide.","Downstream items already changed.","Downstream items still at risk."]},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Communicating a new plan before it is confirmed.","Accepting a replacement without checking the next meeting.","Cancelling a booking before a replacement is secured when no instruction requires it.","Forgetting to update calendar links and local times.","Giving sensitive itinerary details to people who only need the revised meeting time.","Failing to document fees, credits, or changes for later reconciliation."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Write a contingency handoff for a fictional executive whose flight is cancelled, hotel booking starts that night, and first client meeting is at 9:00 AM the next day. Provide three options with trade-offs and identify the decision deadline."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'changes-disruptions-and-contingency-handoffs';

update public.training_lessons l
set content = '[{"type":"heading","text":"Executives do not need another giant to-do list"},{"type":"paragraph","text":"An executive often has dozens of active responsibilities, but only a small number require their attention at any given moment. A good Executive VA separates work that can be delegated or processed from decisions that truly need the executive."},{"type":"heading","text":"Build separate queues"},{"type":"list","items":["Decisions needed: only items requiring executive judgment or approval.","Delegated work: tasks owned by someone else but needing visibility or follow-up.","Waiting: external or internal dependencies.","Deadlines: time-sensitive commitments that may create consequences.","Upcoming preparation: work needed before meetings, travel, launches, or reviews.","Reference: useful material with no action."]},{"type":"heading","text":"A decision item should be small enough to decide"},{"type":"steps","items":["State the decision in one sentence.","Explain why it matters now.","Provide the relevant facts.","Show realistic options if there are choices.","Show the trade-off.","State the deadline.","Link the full background for deeper review."]},{"type":"callout","title":"Do not bury the ask","text":"If the executive has to read three paragraphs before discovering that you need a yes/no approval by 2 PM, the decision item is badly designed."},{"type":"heading","text":"Prioritization factors"},{"type":"list","items":["Consequence of delay.","Number of people blocked.","Customer or employee impact.","Financial or legal exposure.","Irreversible versus reversible action.","Deadline.","Strategic importance.","Whether only the executive can act."]},{"type":"heading","text":"Avoid fake urgency"},{"type":"paragraph","text":"Not everything important should interrupt the executive immediately. Group non-urgent decisions into review windows when possible. Reserve immediate escalation for issues that genuinely cannot wait without creating material risk or blocking critical work."},{"type":"scenario","title":"Seven approvals before lunch","text":"You have seven items: a routine software renewal, a candidate offer, a customer refund above policy limit, a meeting-room change, a new vendor contract, a social post approval, and a board-paper deadline. Sort them by consequence and whether the executive is actually needed. Move routine administrative work out of the executive decision queue where authority permits."},{"type":"heading","text":"Track delegated work without micromanaging"},{"type":"list","items":["Record owner and due date.","Define the expected output.","Record the last meaningful update.","Schedule the next checkpoint.","Escalate only when the work is blocked, overdue, or materially off track.","Close the loop when complete."]},{"type":"heading","text":"Daily decision review"},{"type":"steps","items":["Remove decisions already resolved.","Combine duplicates.","Re-check deadlines.","Add new context.","Move tasks that no longer require the executive to the right owner.","Put the highest-consequence items first.","Prepare the executive''s review in a format they can process quickly."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Create a fictional decision queue with ten items. Reduce it to the five that genuinely require the executive, then write each item in a decision-ready format: decision, facts, options, deadline, and source link."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'priority-management-and-decision-queues';

update public.training_lessons l
set content = '[{"type":"heading","text":"Executive research should reduce uncertainty"},{"type":"paragraph","text":"A long document is not automatically useful research. Executive research should answer a defined question, use defensible sources, distinguish fact from inference, show meaningful trade-offs, and make uncertainty visible."},{"type":"heading","text":"Start with the decision question"},{"type":"list","items":["What is the executive trying to decide or understand?","What would change the decision?","What geography, customer segment, time period, or product scope matters?","What sources are acceptable?","How current must the information be?","What output format is needed?"]},{"type":"heading","text":"Source discipline"},{"type":"steps","items":["Start with primary or authoritative sources where possible.","Use reputable secondary sources for context and comparison.","Check publication and event dates.","Verify numbers across the original source rather than repeating snippets.","Record URLs or document locations.","Mark estimates, opinions, and unverified claims clearly.","Do not cite an AI-generated answer as the source."]},{"type":"callout","title":"AI can accelerate research, but it cannot be the evidence","text":"Use AI to suggest questions, organize notes, or summarize material you have verified. Do not present AI-generated facts, statistics, quotations, company information, or legal/financial claims without checking the underlying source."},{"type":"heading","text":"Executive brief structure"},{"type":"steps","items":["Question or decision.","Bottom line in two to four sentences.","Key evidence.","Options or implications.","Risks and unknowns.","Recommended administrative next step if appropriate.","Sources."]},{"type":"heading","text":"What to leave out"},{"type":"list","items":["Background that does not affect the question.","Five examples when two representative examples are enough.","Repeated wording from source material.","Unsupported conclusions.","Statistics without date, geography, or source.","Decorative charts that do not change understanding."]},{"type":"scenario","title":"Research three vendors","text":"Your executive asks for ''the best CRM''. That question is too broad. Clarify team size, budget, must-have workflow, integrations, current pain points, and decision deadline. Then compare the vendors using those criteria rather than producing a generic feature list."},{"type":"heading","text":"Distinguish fact, analysis, and recommendation"},{"type":"list","items":["Fact: supported directly by a reliable source.","Analysis: your synthesis of multiple facts; explain the reasoning.","Recommendation: a proposed choice or next action; show the criteria and uncertainty.","Unknown: information you could not verify or that depends on the executive''s preference."]},{"type":"heading","text":"Quality check"},{"type":"list","items":["Does the first paragraph answer the actual question?","Are all important numbers dated and sourced?","Are options compared using the same criteria?","Are unknowns visible?","Could the executive reach the source in one click?","Did you avoid presenting opinion as fact?"]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Prepare a fictional one-page brief comparing three project-management tools for a 15-person agency. Define five criteria, cite fictional source placeholders, separate fact from analysis, and end with the two decisions the executive still needs to make."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'research-briefs-and-executive-summaries';

update public.training_lessons l
set content = '[{"type":"heading","text":"A reliable rhythm reduces repeated checking"},{"type":"paragraph","text":"Executive support works best when the executive does not need to ask, ''What am I forgetting?'', ''Did they reply?'', or ''What changed?'' every few hours. A consistent operating rhythm makes the day predictable without filling it with status meetings."},{"type":"heading","text":"Morning review"},{"type":"steps","items":["Check calendar changes, travel, and location.","Check genuine urgent inbox items.","Review today''s meetings and preparation requirements.","Review decision deadlines.","Check delegated work that may block today''s commitments.","Confirm high-risk or time-sensitive follow-ups.","Prepare a concise morning note if the executive uses one."]},{"type":"heading","text":"Midday checkpoint"},{"type":"list","items":["New urgent issue or material schedule change.","Decision that must happen before the next meeting or deadline.","Blocked task that cannot wait until end of day.","Travel or customer disruption.","Everything else can usually remain in the task system or end-of-day summary."]},{"type":"callout","title":"Do not create status noise","text":"A good operating rhythm reduces interruptions. It does not mean sending a message every time you complete a task. Group routine updates and interrupt only for issues that meet the agreed threshold."},{"type":"heading","text":"End-of-day handoff"},{"type":"steps","items":["Completed: important outcomes achieved.","Decisions made: include what changed because of them.","Waiting: who owes what and when you will follow up.","Blocked: what cannot move and why.","Tomorrow: first commitments and required preparation.","Executive decisions: only items that genuinely need their input.","Risks: deadlines, stakeholder issues, travel, money, privacy, or operational concerns."]},{"type":"heading","text":"Write handoffs for action"},{"type":"paragraph","text":"Avoid diary-style reporting such as ''I emailed Sarah, then I updated the sheet, then I checked the calendar.'' Use outcome language: ''Client renewal: pricing approval still needed by 11 AM tomorrow; draft response and account history are linked. Owner: Executive.''"},{"type":"scenario","title":"A busy day with no emergencies","text":"You completed 23 routine tasks, but only four matter to tomorrow: an unsigned proposal, an executive decision on a candidate, a rescheduled investor call, and a vendor waiting on approval. The handoff should center those four items, not the other 19."},{"type":"heading","text":"Continuity when another assistant takes over"},{"type":"list","items":["Current priorities.","Calendar risks.","Pending decisions.","Open stakeholder issues.","Travel or logistics changes.","Where source documents live.","What has already been communicated.","What must not be communicated yet."]},{"type":"heading","text":"Daily QA"},{"type":"list","items":["No genuine urgent item is sitting unassigned.","Tomorrow''s first meeting has the required preparation.","Every active commitment has an owner.","Every waiting item has a next follow-up if needed.","The decision queue is current.","Sensitive files and notes are stored correctly.","The executive can understand the day without opening ten systems."]},{"type":"heading","text":"Practice"},{"type":"paragraph","text":"Write a fictional morning brief and end-of-day handoff for the same executive. The morning brief should contain no more than seven items. The evening handoff should show outcomes, decisions, waiting items, blockers, tomorrow''s first commitments, and any remaining risk."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'daily-operating-rhythm-and-end-of-day-handoffs';

update public.training_lessons l
set content = '[{"type":"heading","text":"Final practice: run an executive-support day"},{"type":"paragraph","text":"This simulation tests whether you can combine judgment, confidentiality, inbox and calendar management, meeting preparation, travel, research, decisions, and handoffs. Every person and company in this scenario is fictional."},{"type":"heading","text":"Scenario background"},{"type":"paragraph","text":"You support the founder of a 40-person services company. The founder works across two time zones, manages key customers, approves senior hires and larger purchases, and travels regularly. You have documented authority to schedule routine meetings, draft routine replies, and prepare travel options, but you cannot approve spending above the stated limit, sign contracts, disclose confidential HR information, or make commercial commitments without approval."},{"type":"heading","text":"Your incoming work"},{"type":"list","items":["A major client emails that they are unhappy with a missed deadline and asks to speak today.","The founder''s calendar has a leadership meeting ending 15 minutes before an in-person customer meeting across town.","A confidential senior-candidate interview is on the calendar, and a colleague asks why the founder is unavailable.","A supplier emails new bank details and asks for an urgent payment.","Tomorrow''s investor meeting has no briefing note, and the latest revenue file differs from the figure in last week''s deck.","The founder''s evening flight is cancelled while they are still in a customer meeting.","Three team members are waiting on separate decisions from the founder.","A long email thread contains a draft renewal proposal and a request to move the start date.","The founder asks you to compare two replacement flight options and ''sort the rest''.","You need to leave a clear end-of-day handoff for a colleague in another time zone."]},{"type":"heading","text":"Part 1: Prioritise and classify"},{"type":"steps","items":["Rank the ten items by consequence of delay.","Classify each as decision, action, reply, meeting, waiting, reference, or security/risk escalation.","Mark which items you can complete independently.","Mark which need executive approval.","Mark any item that needs a security, finance, HR, legal, or other specialist process."]},{"type":"heading","text":"Part 2: Produce the work"},{"type":"list","items":["Draft a concise acknowledgement to the unhappy client without making an unauthorized promise.","Propose a calendar solution for the travel-time conflict.","Write the safe response to the colleague asking about the confidential interview.","Write the payment-verification escalation note for the changed bank details.","Create a one-page investor briefing-note outline and flag the revenue discrepancy.","Compare two replacement travel options and show the downstream changes each would require.","Turn the three founder decisions into decision-ready queue items.","Summarize the renewal email thread and identify the exact decision required.","Create the end-of-day handoff for the next assistant."]},{"type":"callout","title":"Assessment standard","text":"You are assessed on prioritization, factual accuracy, confidentiality, authority boundaries, clarity, decision preparation, continuity, and whether your actions reduce executive friction without creating hidden risk."},{"type":"heading","text":"Part 3: Self-review"},{"type":"list","items":["Did you surface the client issue without promising an outcome you cannot approve?","Did you protect the confidential interview?","Did you treat changed bank details as a verification issue rather than normal admin?","Did you distinguish the conflicting revenue figures instead of choosing one?","Did you check downstream travel dependencies?","Did every executive decision become small enough to decide quickly?","Did your handoff make the next person''s first actions obvious?"]},{"type":"heading","text":"What excellent work looks like"},{"type":"paragraph","text":"Excellent Executive VA work is quiet, precise, and traceable. It removes avoidable decisions from the executive while making the important decisions easier. It protects confidential information, catches dependencies, communicates only what is confirmed, and leaves a reliable operating record."},{"type":"scenario","title":"Optional stretch scenario","text":"At 5:45 PM, a board member asks for the investor deck immediately. The revenue discrepancy is still unresolved. Explain what you would send, what you would not send, how you would describe the unresolved figure, and whose approval you would seek before circulating anything that could be misleading."}]'::jsonb,
    estimated_minutes = 30,
    content_version = l.content_version + 1,
    reviewed_by = null,
    last_reviewed_at = null,
    is_published = false,
    updated_at = now()
from public.training_modules m
join public.training_courses c on c.id = m.course_id
where l.module_id = m.id
  and c.slug = 'executive-virtual-assistant'
  and l.slug = 'composite-executive-va-work-simulation';

update public.training_assessments
set instructions = 'Complete the composite Executive VA work simulation from the final lesson and submit: (1) a prioritized and classified work queue, (2) a safe client acknowledgement, (3) a corrected calendar plan, (4) a confidentiality-safe response about the private interview, (5) a payment-verification escalation note, (6) an investor briefing-note outline with the conflicting revenue figure clearly flagged, (7) a comparison of two travel-contingency options and their downstream impact, (8) three decision-ready executive queue items, (9) a renewal-thread summary with the exact decision required, and (10) an end-of-day handoff. Review should assess prioritization, factual accuracy, confidentiality, authority boundaries, executive communication, decision preparation, continuity, and escalation judgment. The learner must not invent approvals, disclose confidential information, approve unverified payments, or make commercial commitments outside delegated authority.',
    assessment_type = 'practical',
    pass_score = null,
    is_published = false,
    updated_at = now()
where course_id = (select id from public.training_courses where slug='executive-virtual-assistant');
